import{z as i,x as p,o as r,c as A,q as B,j as s,D as o,d as e,s as l,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"科斯定理与交易成本","description":"","frontmatter":{"title":"科斯定理与交易成本","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/coase-theorem.md","filePath":"econ/coase-theorem.md","lastUpdated":1791063341000}'),d={name:"econ/coase-theorem.md"};function m(h,a,D,c,C,f){const t=p("Mermaid");return r(),A("div",null,[a[2]||(a[2]=B('<h1 id="科斯定理与交易成本" tabindex="-1">科斯定理与交易成本 <a class="header-anchor" href="#科斯定理与交易成本" aria-label="Permalink to &quot;科斯定理与交易成本&quot;">​</a></h1><div class="epigraph"><p>若交易成本为零，权利的初始分配不影响资源配置的效率；有摩擦时，法律规则本身就是经济问题。</p><footer>—— 据 Coase, The Problem of Social Cost, Journal of Law and Economics, 1960 整理</footer></div><p><a href="/econ/missing-markets">上一课</a>（缺失市场）。用庇古税把漏列的边际塞回私人一阶条件，但计划者必须知道 \\(\\mathrm{MD}(q^*)\\)。缺口是：当事双方若能自己谈，还要不要这个税？科斯把问题从「算准税率」换成「界定权利、看谈判成本」。本课钉零成本基准与摩擦打开后的含义，不把科斯写成「政府永远多余」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>庇古默认损害方向是单向的：工厂害邻居，所以罚工厂。科斯指出相互性：禁止工厂等于损害工厂使用空气的权利。有效性问的是：权利放在哪一边，事后的生产与损害是否还能被谈回社会最优。若谈判没有成本，初始权利只改变谁向谁付钱，不改变最终的 \\(q^*\\)。</p><p><span class="marginnote">术语翻译：「相互性」就是说损害从来是相对的——不让工厂冒烟，对工厂就是损害；让工厂随便冒烟，对洗衣店就是损害。真正的问题不是「谁在害谁」，而是「这份稀缺的空气该归谁用」：把排放权当成一件可以买卖的财产，问题就从道德指控变成了定价。</span></p><p>缺口因此不是再写一条 \\(\\mathrm{MD}\\) 曲线，而是：在<a href="/econ/core-equivalence">核</a>那种可结盟逻辑里，把「排放权」当作可转让禀赋。两人、权利清晰、转移可执行时，核收缩到有效点附近——这与埃奇沃思透镜是同一几何，只是商品多了一维权利。</p><h3 id="科斯定理不是科斯写的那五个字" tabindex="-1">科斯定理不是科斯写的那五个字 <a class="header-anchor" href="#科斯定理不是科斯写的那五个字" aria-label="Permalink to &quot;科斯定理不是科斯写的那五个字&quot;">​</a></h3><p>Stigler 后来才叫它定理。Coase 原文的重点在后半：交易成本为正时，初始权利与责任规则改变哪些交易发生得起。零成本只是对照。把原文读成「放任即可」，丢掉了摩擦那一半。</p><p><span class="marginnote">教具：工厂产值与洗衣店损失。权利给洗衣店，工厂买排放权直到边际产值等于边际损失；权利给工厂，洗衣店付钱让工厂减产，停在同一点。支付方向相反，有效点相同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：两人、完全信息、权利可转让、合约可强制执行、效用可转移（或至少可谈判到帕累托边界）。结论：有效配置与权利的初始分配无关；分配效应当然有关。这是<a href="/econ/welfare-theorems">第二福利定理</a>的私人版本：总额转移在这里是权利本身，市场（谈判）去实现有效点。</p><p>交易成本 \\(c\\gt 0\\) 时，只有增益超过 \\(c\\) 的交易发生。权利放在「本来就会做有效选择」的一方，可以省掉谈判；放错边，谈判又谈不成，就停在无效点。于是法律的比较静态是：哪一种初始规则使必须发生的交易更少、更便宜。</p>',13)),(r(),s(n,null,{default:o(()=>[l(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20RIGHT%5B%22%E6%8E%92%E6%94%BE%E6%9D%83%E7%9A%84%E5%88%9D%E5%A7%8B%E5%88%86%E9%85%8D%22%5D%20--%3E%20ZERO%5B%22c%20%3D%200%EF%BC%9A%E8%B0%88%E5%88%A4%E5%88%B0%E6%9C%89%E6%95%88%E7%82%B9%22%5D%0A%20%20RIGHT%20--%3E%20FRIC%5B%22c%20%3E%200%EF%BC%9A%E6%9C%89%E4%BA%9B%E4%BA%A4%E6%98%93%E4%B8%8D%E5%8F%91%E7%94%9F%22%5D%0A%20%20ZERO%20--%3E%20DIST%5B%22%E5%8F%AA%E6%94%B9%E5%88%86%E9%85%8D%EF%BC%8C%E4%B8%8D%E6%94%B9%20q*%22%5D%0A%20%20FRIC%20--%3E%20LAW%5B%22%E8%A7%84%E5%88%99%E6%9C%AC%E8%BA%AB%E5%BD%B1%E5%93%8D%E6%95%88%E7%8E%87%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"多人、免费搭车时，谈判联盟复制了核的阻塞困难：人越多，越接近下一课的公共物品。科斯基准在小数目上最干净。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("零成本时，价格（或一次性支付）把外部性重新商品化。权利是禀赋，谈判是交易，有效性回到第一定理。税变成多余——不是因为损害不存在，而是因为市场已经被补全。支付方向随初始权利变，这是分配； \\(q^*\\) 不变，这是效率。两人盒里把权利画成禀赋点，谈判沿透镜走到合同曲线，与"),E("a",{href:"/econ/edgeworth-pareto"},"埃奇沃思"),e("同一张图。")],-1)),(r(),s(n,null,{default:o(()=>[l(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20R1%5B%22%E6%9D%83%E5%88%A9%E7%BB%99%E6%B4%97%E8%A1%A3%E5%BA%97%EF%BC%9A%E5%B7%A5%E5%8E%82%E9%A1%BB%E4%B9%B0%E6%8E%92%E6%94%BE%E6%9D%83%22%5D%20--%3E%20B1%5B%22%E5%B7%A5%E5%8E%82%E4%B8%80%E7%9B%B4%E4%B9%B0%E5%88%B0%E4%BA%A7%E5%80%BC%20%3D%20%E8%BE%B9%E9%99%85%E6%8D%9F%E5%A4%B1%E9%82%A3%E5%8D%95%E4%BD%8D%22%5D%0A%20%20R2%5B%22%E6%9D%83%E5%88%A9%E7%BB%99%E5%B7%A5%E5%8E%82%EF%BC%9A%E6%B4%97%E8%A1%A3%E5%BA%97%E4%BB%98%E9%92%B1%E6%B1%82%E5%87%8F%E4%BA%A7%22%5D%20--%3E%20B2%5B%22%E6%B4%97%E8%A1%A3%E5%BA%97%E4%B9%B0%E5%88%B0%E3%80%8C%E5%86%8D%E5%87%8F%E4%B8%80%E5%8D%95%E4%BD%8D%E4%B8%8D%E5%80%BC%E3%80%8D%E9%82%A3%E5%8D%95%E4%BD%8D%22%5D%0A%20%20B1%20--%3E%20SAME%5B%22%E5%81%9C%E5%9C%A8%E5%90%8C%E4%B8%80%E6%9C%89%E6%95%88%E7%82%B9%20q*%22%5D%0A%20%20B2%20--%3E%20SAME%0A%20%20SAME%20--%3E%20DIFF%5B%22%E5%B7%AE%E5%88%AB%E5%8F%AA%E5%9C%A8%E8%B0%81%E5%90%91%E8%B0%81%E5%BC%80%E6%94%AF%E7%A5%A8%EF%BC%88%E5%88%86%E9%85%8D%EF%BC%89%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p><span class="marginnote">数字实例：某单位排放给工厂挣 80 元、让洗衣店损失 30 元——无论权利给谁，这单位都会排放（80 与 30 的差总能被谈判分掉）；另一单位只挣 20 元、损失 30 元——无论权利给谁，它都不会排放。权利像把方向盘装在哪边，最终停的车速一样，只是油钱谁出变了。</span></p><p>摩擦破坏的是「补全」这一步。写合约要描述状态、监测排放、防止事后敲竹杠。权利模糊时，双方争的是权利本身，不是排放数量。此时庇古税与科斯谈判都缺信息：前者缺 \\(\\mathrm{MD}\\)，后者缺可执行的产权。比较的是两种信息体制，不是「市场对政府」的口号。人数一多，每个受益者都想让别人去谈，摩擦与免费搭车叠在一起——那是下一课。</p><h3 id="企业是降低交易成本的一种装置" tabindex="-1">企业是降低交易成本的一种装置 <a class="header-anchor" href="#企业是降低交易成本的一种装置" aria-label="Permalink to &quot;企业是降低交易成本的一种装置&quot;">​</a></h3><p>Coase 更早的《企业的性质》把企业看成用权威替代市场谈判。若工厂和洗衣店合并，排放变成内部转移定价，双边外部消失。合并本身有组织成本，超过这个成本就不如继续做两个主体再谈判或再征税。本课不重写厂商技术，只把治理结构放进可行性：税、禁令、合并、法庭，是替代的契约形式。</p><p>拟线性（或可转移效用）关掉收入效应，教具才有「 \\(q^*\\) 与权利无关」。效用不可转移时，权利带来的财富会改需求，有效点可以微移。不要在一般偏好里硬说数量一字不差。</p><p><span class="marginnote">权利必须可让渡。若「清洁空气」无法排除搭便车的居民，双边谈判组不起来。定理的域是稀少当事人、权利清晰、法庭便宜。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>完全信息是关键。不对称信息下列出菜单，谈判本身有逆向选择与信号，要等到本课程的信息课序。不可分、非凸时谈判可能停在错误的角点。收入效应大、效用不可转移时，「与初始分配无关」只对效率近似成立，对分配不成立。</p><p><span class="marginnote">常见误区：把科斯定理缩写成「政府别管，市场自己搞定」。实际上零成本基准只是参照系，Coase 原文的重心是后半：谈判、计量、执行都有成本，多数环境纠纷里当事人成千上万、根本坐不到一张桌前。这时初始权利怎么定、法庭怎么判，就直接决定效率——这是在给立法者派活，不是免职。</span></p><p>也不要把科斯用来给限价簿背书。权利交易仍是抽象的净转移，不是订单簿上的排队。后课公共物品把非竞争、非排他推到极端，谈判的联盟规模爆炸。</p><p>权利若不可转让，零成本结论立刻垮：谈判没有商品可交。科斯要的是可交易的产权，不是「贴一张告示」。</p><p>后课默认：零交易成本下，清晰产权可使外部性内部化；正成本时，权利分配进入效率。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>外部性有相互性；有效性问最终 \\(q^*\\)，不先验惩罚某一方。</li><li>零成本谈判下，初始权利只改分配；正成本下，规则改效率。</li><li>科斯是补全市场，不是取消损害。</li><li>人数一多，谈判靠近免费搭车。</li><li>出处：Coase, <em>JLE</em> 1960；定理一名来自 Stigler 的转述。</li></ul>',14))])}const q=i(d,[["render",m]]);export{_ as __pageData,q as default};
